"""Build an offline, mobile research page. This is not a playable v4 catalog."""
import json,base64,html
from pathlib import Path
from PIL import Image
from io import BytesIO
ROOT=Path(__file__).resolve().parents[2];SRC=ROOT/'product/audits/colony-flow-early-2026-10-19';OUT=ROOT/'product/previews/gameplay-v4-plan/index.html'
def load(name):return json.loads((SRC/name).read_text())
def uri(path):
 im=Image.open(path).convert('RGB');im.thumbnail((1000,1801));buf=BytesIO();im.save(buf,format='WEBP',quality=84);return 'data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
